-- Migración de DATOS HubSpot → CRM (generada desde los CSV; misma lógica validada en dev).
-- Contactos: 2938 | Negocios: 1846. Idempotente (dedup por hubspot_id + correo/tel).
-- Requiere columnas hubspot_id (migración 20260730130000). Dueños por email; etapas por nombre normalizado.
BEGIN;
-- normalizador de etapas (acentos/mayúsculas/artículos) — igual que el alias del front
CREATE OR REPLACE FUNCTION pg_temp.normet(t text) RETURNS text AS $NE$ SELECT btrim(regexp_replace(regexp_replace(lower(translate(coalesce(t,''),'áéíóúüñ','aeiouun')), '\m(el|la|los|las)\M','','g'), '\s+',' ','g')) $NE$ LANGUAGE sql IMMUTABLE;

-- ===== Fase 0: pipelines + etapas (idempotente por nombre) =====

-- ===== Fase 1: contactos (staging + inserción con FKs remapeadas) =====
CREATE TEMP TABLE _stg_c (hub text, nombre text, email text, telefono text, tipo int, estatus text, etapa text, owner_email text, fecha timestamp, nota text, tarea text) ON COMMIT DROP;
DO $DO$
DECLARE r record; v_pid int; v_eid bigint; v_owner uuid;
BEGIN
  FOR r IN SELECT * FROM _stg_c LOOP
    IF r.hub IS NOT NULL AND EXISTS (SELECT 1 FROM public.crm_leads_atribucion WHERE hubspot_id = r.hub) THEN CONTINUE; END IF;
    -- ¿ya existe como contacto (por correo o tel)? -> marca hubspot_id (para ligar negocios) y salta (idempotente).
    v_eid := NULL;
    IF r.email IS NOT NULL THEN
      SELECT e.id INTO v_eid FROM public.entidades_relacionadas e JOIN public.personas p ON p.id=e.id_persona
        WHERE e.activo AND p.activo AND e.id_tipo_entidad IN (2,7) AND lower(p.email)=lower(r.email)
        ORDER BY (e.id_tipo_entidad=7) DESC LIMIT 1;
    END IF;
    IF v_eid IS NULL AND r.telefono IS NOT NULL THEN
      SELECT e.id INTO v_eid FROM public.entidades_relacionadas e JOIN public.personas p ON p.id=e.id_persona
        WHERE e.activo AND p.activo AND e.id_tipo_entidad IN (2,7) AND right(regexp_replace(p.telefono,'\D','','g'),10)=right(regexp_replace(r.telefono,'\D','','g'),10)
        ORDER BY (e.id_tipo_entidad=7) DESC LIMIT 1;
    END IF;
    IF v_eid IS NOT NULL THEN
      UPDATE public.crm_leads_atribucion SET hubspot_id=COALESCE(hubspot_id,r.hub) WHERE id_entidad_relacionada=v_eid;
      CONTINUE;
    END IF;
    v_owner := (SELECT auth_user_id FROM public.usuarios WHERE lower(email)=lower(r.owner_email) LIMIT 1);
    IF r.email IS NOT NULL THEN
      VALUES ('pf',r.nombre,r.email,r.telefono,true,COALESCE(r.fecha,CURRENT_TIMESTAMP))
      ON CONFLICT (email) DO UPDATE SET activo=true RETURNING id INTO v_pid;
    ELSE
      SELECT p.id INTO v_pid FROM public.personas p WHERE p.activo AND p.telefono IS NOT NULL AND right(regexp_replace(p.telefono,'\D','','g'),10)=right(regexp_replace(r.telefono,'\D','','g'),10) LIMIT 1;
      IF v_pid IS NULL THEN
        VALUES ('pf',r.nombre,NULL,r.telefono,true,COALESCE(r.fecha,CURRENT_TIMESTAMP)) RETURNING id INTO v_pid;
      END IF;
    END IF;
    VALUES (v_pid,r.tipo,NULL,true,COALESCE(r.fecha,CURRENT_TIMESTAMP)) RETURNING id INTO v_eid;
    VALUES (v_eid,r.estatus,r.etapa,v_owner,'importacion',r.hub,COALESCE(r.fecha,now()));
    IF r.nota IS NOT NULL THEN INSERT INTO public.crm_notas (id_entidad_relacionada,id_usuario,contenido) VALUES (v_eid,NULL,r.nota); END IF;
    IF r.tarea IS NOT NULL THEN INSERT INTO public.crm_tareas (id_entidad_relacionada,id_usuario_asignado,titulo,tipo,prioridad,estatus,descripcion)
      VALUES (v_eid,v_owner,left(r.tarea,120),'tarea','media','pendiente',r.tarea); END IF;
  END LOOP;
END $DO$;

-- ===== Fase 2: negocios (staging + INSERT..SELECT; liga por hubspot_id del contacto) =====
CREATE TEMP TABLE _stg_n (hub text, nombre text, pipeline text, etapa text, valor numeric, owner_email text, f_cre timestamp, f_cie date, tipo text, contact_hub text) ON COMMIT DROP;
SELECT s.nombre, pp.id,
       COALESCE(
         (SELECT e.id FROM public.crm_pipeline_etapas e WHERE e.id_pipeline=pp.id AND pg_temp.normet(e.nombre)=pg_temp.normet(s.etapa) LIMIT 1),
         (SELECT e.id FROM public.crm_pipeline_etapas e WHERE e.id_pipeline=pp.id ORDER BY e.orden LIMIT 1)
       ),
       s.valor, 'MXN',
       (SELECT auth_user_id FROM public.usuarios WHERE lower(email)=lower(s.owner_email) LIMIT 1),
       s.f_cie, s.tipo,
       (SELECT la.id_entidad_relacionada FROM public.crm_leads_atribucion la WHERE la.hubspot_id=s.contact_hub LIMIT 1),
       s.hub, true, COALESCE(s.f_cre, now())
FROM _stg_n s
JOIN public.crm_pipelines pp ON lower(pp.nombre)=lower(s.pipeline)
WHERE NOT EXISTS (SELECT 1 FROM public.crm_negocios n WHERE n.hubspot_id = s.hub)
  AND NOT EXISTS (
    SELECT 1 FROM public.crm_negocios n
    WHERE n.nombre = s.nombre
      AND n.id_entidad_relacionada IS NOT DISTINCT FROM
          (SELECT la.id_entidad_relacionada FROM public.crm_leads_atribucion la WHERE la.hubspot_id = s.contact_hub LIMIT 1)
  );

COMMIT;
